from itertools import permutations
def rx(c): return {'U':c['F'],'F':c['D'],'D':c['B'],'B':c['U'],'L':c['L'],'R':c['R']}
def ry(c): return {'F':c['R'],'R':c['B'],'B':c['L'],'L':c['F'],'U':c['U'],'D':c['D']}
def orients(c):
    seen=[];stack=[c]
    while stack:
        x=stack.pop()
        k=tuple(sorted(x.items()))
        if k in [tuple(sorted(s.items())) for s in seen]: continue
        seen.append(x); stack+= [rx(x),ry(x)]
    return seen
def opposite_candidates(letters, views, target):
    res=set()
    for p in permutations(letters):
        c=dict(zip('UDFBLR',p))
        os_=orients(c)
        if all(any((o['U'],o['F'],o['R'])==v for o in os_) for v in views):
            res.add(c[{'U':'D','D':'U','F':'B','B':'F','L':'R','R':'L'}[[k for k in c if c[k]==target][0]]])
    return res

